29: export function zeroUsageTotals(): UsageTotals {
30:   return {
31:     inputTokens: 0,
32:     outputTokens: 0,
33:     cacheReadTokens: 0,
34:     cacheWriteTokens: 0,
35:     reasoningTokens: 0,
