52: export function accumulateUsage(target: UsageTotals, entry: UsageLedgerEntry): UsageTotals {
53:   return {
54:     inputTokens: target.inputTokens + (entry.inputTokens ?? 0),
55:     outputTokens: target.outputTokens + (entry.outputTokens ?? 0),
56:     cacheReadTokens: target.cacheReadTokens + (entry.cacheReadTokens ?? 0),
57:     cacheWriteTokens: target.cacheWriteTokens + (entry.cacheWriteTokens ?? 0),
58:     reasoningTokens: target.reasoningTokens + (entry.reasoningTokens ?? 0),
59:     totalTokens: target.totalTokens + (entry.totalTokens ?? 0),
60:     costUsd: target.costUsd + (entry.costUsd ?? 0),
61:     hasUnknownTokens: target.hasUnknownTokens || entry.totalTokens === null,
62:     hasUnknownCost: target.hasUnknownCost || entry.costUsd === null,
63:   };
64: }
