178: export function applyTaskMetaToWorkerProjection(
179:   state: WorkerProjectionState,
180:   issueId: IssueId,
181:   meta: TaskMeta | undefined,
182: ): Pick<WorkerProjectionState, "workers"> | null {
183:   const key = workerKey(issueId);
184:   const existing = state.workers.get(key);
185:   if (!existing) return null;
186:   const workers = new Map(state.workers);
187:   workers.set(key, updateWorkerMeta(existing, meta));
188:   return { workers };
189: }
