191: export function applyUsageRecordedToWorkerProjection(
192:   state: WorkerProjectionState,
193:   entry: UsageLedgerEntry,
194:   at: string,
195: ): Pick<WorkerProjectionState, "runUsage" | "runStreamingUsage"> | Pick<WorkerProjectionState, "workers" | "runUsage"> {
196:   const runUsage = accumulateUsage(state.runUsage, entry);
197:   if (entry.issueId === undefined) {
198:     return { runUsage, runStreamingUsage: null };
199:   }
200: 
201:   const workers = new Map(state.workers);
202:   const key = workerKey(entry.issueId);
203:   const existing = workers.get(key) ?? createWorkerRow(entry.issueId, "scheduled");
204:   const currentPhase = existing.phase;
205:   const phaseRecord = existing.phases.get(currentPhase) ?? { contextTokens: null, maxContext: null };
206:   const updatedPhases = new Map(existing.phases);
207:   updatedPhases.set(currentPhase, {
208:     ...phaseRecord,
209:     contextTokens: entry.contextTokens ?? phaseRecord.contextTokens,
210:     maxContext: entry.maxContext ?? phaseRecord.maxContext,
211:   });
212:   workers.set(key, {
213:     ...existing,
214:     phases: updatedPhases,
215:     latestAt: at,
216:     latestInputTokens: entry.inputTokens,
217:     latestContextTokens: entry.contextTokens ?? existing.latestContextTokens,
218:     usage: accumulateUsage(existing.usage, entry),
219:     streamingUsage: null,
220:   });
221:   return { workers, runUsage };
222: }
223: 
224: export function applyStreamingUsageToWorkerProjection(
225:   state: WorkerProjectionState,
226:   issueId: IssueId | undefined,
227:   usage: AgentExecutionUsage,
228: ): Pick<WorkerProjectionState, "runStreamingUsage"> | Pick<WorkerProjectionState, "workers"> | null {
229:   if (issueId === undefined) {
230:     return { runStreamingUsage: usage };
231:   }
232:   const key = workerKey(issueId);
233:   const workers = new Map(state.workers);
234:   const existing = workers.get(key);
235:   if (!existing) return null;
236:   const currentPhase = existing.phase;
237:   const phaseRecord = existing.phases.get(currentPhase) ?? { contextTokens: null, maxContext: null };
238:   const updatedPhases = new Map(existing.phases);
239:   updatedPhases.set(currentPhase, {
240:     contextTokens: usage.contextTokens ?? phaseRecord.contextTokens,
241:     maxContext: usage.maxContext ?? phaseRecord.maxContext,
242:   });
243:   workers.set(key, {
244:     ...existing,
245:     phases: updatedPhases,
246:     streamingUsage: usage,
247:     latestInputTokens: usage.inputTokens,
248:     latestContextTokens: usage.contextTokens ?? existing.latestContextTokens,
249:   });
250:   return { workers };
251: }
