253: export function displayRunUsage(state: WorkerProjectionState): UsageTotals {
254:   let totals = zeroUsageTotals();
255:   for (const worker of state.workers.values()) {
256:     if (worker.streamingUsage !== null) {
257:       totals = accumulateStreamingUsage(totals, worker.streamingUsage);
258:     }
259:   }
260:   if (state.runStreamingUsage !== null) {
261:     totals = accumulateStreamingUsage(totals, state.runStreamingUsage);
262:   }
263:   return totals;
264: }
265: 
266: export function hasInProgressUsage(state: WorkerProjectionState): boolean {
267:   const totals = displayRunUsage(state);
268:   return totals.inputTokens > 0
269:     || totals.outputTokens > 0
270:     || totals.cacheReadTokens > 0
271:     || totals.cacheWriteTokens > 0
272:     || totals.reasoningTokens > 0
273:     || totals.totalTokens > 0
274:     || totals.costUsd > 0
275:     || totals.hasUnknownTokens
276:     || totals.hasUnknownCost;
277: }
278: 
279: export function displayInputTokens(worker: WorkerDashboardRow): number {
280:   return worker.usage.inputTokens + (worker.streamingUsage?.inputTokens ?? 0);
281: }
282: 
283: export function displayOutputTokens(worker: WorkerDashboardRow): number {
284:   return worker.usage.outputTokens + (worker.streamingUsage?.outputTokens ?? 0);
285: }
286: 
287: export function displayHasUnknownCost(worker: WorkerDashboardRow): boolean {
288:   if (worker.usage.hasUnknownCost) return true;
289:   return worker.streamingUsage !== null && worker.streamingUsage.costUsd === null;
290: }
291: 
292: export function formatDisplayCost(worker: WorkerDashboardRow): string {
293:   if (displayHasUnknownCost(worker)) return "unknown";
294:   const total = worker.usage.costUsd + (worker.streamingUsage?.costUsd ?? 0);
295:   return `$${total.toFixed(2)}`;
296: }
