161: export function applyLoopRunEventToInkState(
162:   state: InkRunViewState,
163:   event: LoopRunEvent,
164:   at: string,
165: ): InkRunViewState {
166:   switch (event.kind) {
167:     case "taskPhaseChanged": {
168:       const workerProjection = applyTaskPhaseToWorkerProjection(state, event, at);
169:       let updatedState: InkRunViewState = { ...state, ...workerProjection };
170:       if (event.from !== null) {
171:         const separator = `── ${String(event.from)} → ${String(event.to)} ──`;
172:         const sourceKey = `issue:${workerKey(event.issueId)}`;
173:         const partial = appendLogFragment(updatedState, sourceKey, event.issueId, event.to, separator, true, at);
174:         updatedState = { ...updatedState, ...partial };
175:       }
176:       return updatedState;
177:     }
178: 
179:     case "taskMetaChanged": {
180:       const workerProjection = applyTaskMetaToWorkerProjection(state, event.issueId, event.meta);
181:       return workerProjection === null ? state : { ...state, ...workerProjection };
182:     }
183: 
184:     case "usageRecorded": {
185:       const workerProjection = applyUsageRecordedToWorkerProjection(state, event.entry, at);
186:       return { ...state, ...workerProjection };
187:     }
188: 
189:     case "streamingUsage": {
190:       const workerProjection = applyStreamingUsageToWorkerProjection(state, event.issueId, event.usage);
191:       return workerProjection === null ? state : { ...state, ...workerProjection };
192:     }
193: 
194:     case "runFinished":
195:       return { ...state, overlay: { kind: "run-finished", outcome: event.outcome } };
196: 
197:     default:
198:       return state;
199:   }
200: }
